Field.Calculation:
If ( 年度 = 2027 ;
 List (
  If ( 年齢22歳以下 = 1 ; " 22歳以下基本年会費　（¥" & 本年度固定費::今年度学割年会費 & "）" ; " 23歳以上基本年会費　（¥" & 本年度固定費::今年度年会費 & "）" ) ;
  If ( 紹介割引額 > 0 ; " 年会費（既納入分調整後・紹介割引前）　¥" & ( 年会費額 + 紹介割引額 ) ; "" ) ;
  If ( 紹介割引額 > 0 ; " 紹介割引（" & 割引適用紹介人数 & "人分）　　　　　　　−¥" & 紹介割引額 ; "" ) ;
  " 本人年会費請求額　　　　　　　　　¥" & 年会費額
 ) ;
 If ( 年齢22歳以下 = 1 ; " 22歳以下基本年会費　（¥" & 本年度固定費::次年度学割年会費 & "）¶ 　　次年度請求額　　　　　　　　　¥" & 年会費額 ; " 23歳以上年会費　（¥" & 本年度固定費::次年度年会費 & "）¶ 　　次年度請求額　　　　　　　　　¥" & 年会費額 )
)
& If ( 家族会員数 = 1 ; "¶" & r家族1文 ; "" )
& If ( 家族会員数 = 2 ; "¶" & r家族2文 ; "" )
& If ( 教室フラグ = 1 ; "¶" & r教室文 ; "" )
& If ( 会報optフラグ = 1 ; "¶" & r会報文 ; "" )
& If ( 会報海外フラグ = 1 ; "¶" & r海外発送文 ; "" )
